}

import { buildSitemapEntries } from "@zedtech/zedkit-seo";
const pages = docs.map((d) => ({ path: `/${d.slug}`, lastModified: d.updatedAt }));
return buildSitemapEntries({ siteUrl, locales: ["en", "fr"], pages });

